"""Compile disposable topology lookup indices, never live vertex positions.

Ordinary edits are sampled from the actual authored objects by Geometry Nodes.
Only builds and managed topology edits need to regenerate these lookup tables.
"""
import bpy
import bmesh


def attribute(mesh, name, domain, values):
    attr = mesh.attributes.get(name) or mesh.attributes.new(name, 'INT', domain)
    if attr.data_type != 'INT' or attr.domain != domain:
        raise ValueError('Invalid live binding attribute '+name)
    attr.data.foreach_set('value', values)


def compile_sources(controller, net):
    name = 'Prochitecture Streets / Live sources / '+controller.st_network.network_uuid
    collection = bpy.data.collections.get(name)
    if collection is None:
        collection = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(collection)
    wanted = {obj for obj in net.sources if obj != controller}
    for obj in tuple(collection.objects):
        if obj not in wanted:
            collection.objects.unlink(obj)
    for obj in wanted:
        if obj.name not in collection.objects:
            collection.objects.link(obj)
    by_object = {obj: ([-1]*len(obj.data.vertices), [-1]*len(obj.data.edges)) for obj in net.sources}
    sections = {}
    vi = ei = 0
    for sid, source in sorted(net.section_sources.items()):
        vp = tuple(range(vi, vi+len(source.vertex_indices)))
        ep = tuple(range(ei, ei+len(source.edge_indices)))
        sections[sid] = (vp, ep)
        a, b = by_object[source.object]
        # In Edit Mode obj.data may lag behind BMesh after a managed subdivision.
        needed_v=max(source.vertex_indices,default=-1)+1
        needed_e=max(source.edge_indices,default=-1)+1
        a.extend([-1]*max(0,needed_v-len(a)));b.extend([-1]*max(0,needed_e-len(b)))
        for local, key in zip(source.vertex_indices, vp): a[local]=key
        for local, key in zip(source.edge_indices, ep): b[local]=key
        vi += len(vp);ei += len(ep)
    if max(vi, ei) >= 2**24:
        raise ValueError('Live binding sort indices exceed exact float integer range; partition the input network')
    for obj, (vp, ep) in by_object.items():
        if obj.mode == 'EDIT':
            bm = bmesh.from_edit_mesh(obj.data)
            bm.verts.ensure_lookup_table();bm.edges.ensure_lookup_table()
            for domain, name, values, items in (('POINT','st_live_vertex_index',vp,bm.verts),('EDGE','st_live_edge_index',ep,bm.edges)):
                layer=items.layers.int.get(name) or items.layers.int.new(name)
                for item in items:item[layer]=values[item.index]
            bmesh.update_edit_mesh(obj.data,loop_triangles=False,destructive=False)
        else:
            attribute(obj.data,'st_live_vertex_index','POINT',vp)
            attribute(obj.data,'st_live_edge_index','EDGE',ep)
            obj.data.update()
    seams = {}
    attached = {member for c in net.connector_records.values() for member in c.members}
    for street in net.canonical.streets:
        for (a, af), (b, bf) in zip(street.sections,street.sections[1:]):
            a_clip = net.section_records[a].clip_end if af else net.section_records[a].clip_start
            b_clip = net.section_records[b].clip_start if bf else net.section_records[b].clip_end
            if a_clip > 0. or b_clip > 0.:
                # Explicit excluded surface extent; the authored semantic
                # Street remains intact but these ends must not be welded.
                continue
            if (a, 1 if af else 0) in attached or (b, 0 if bf else 1) in attached:
                # An explicit internal junction, not a direct Section seam,
                # owns the surface between these ends of the same Street.
                continue
            ap,ae=sections[a];bp,be=sections[b]
            av,an,ax = (ap[-1],ap[-2],ae[-1]) if af else (ap[0],ap[1],ae[0])
            bv,bn,bx = (bp[0],bp[1],be[0]) if bf else (bp[-1],bp[-2],be[-1])
            sign=1 if af==bf else -1
            seams[av]=(bv,bn,an,bx,ax,sign)
            seams[bv]=(av,an,bn,ax,bx,sign)
    return collection, sections, seams, vi, ei


def bind_carrier(mesh, junction, sections, seams, nv):
    points=[];edges=[]
    for street in junction.streets:
        for section in street.sections:
            vp,ep=sections[section.source_id]
            for i,key in enumerate(vp):
                points.append((key,vp[0],vp[-1],vp[min(i+1,len(vp)-1)],1 if i==0 else 2 if i==len(vp)-1 else 0))
            for i,key in enumerate(ep):edges.append((key,ep[0],section.source_id,vp[i],vp[i+1]))
    names=('st_live_vertex_index','st_live_start_index','st_live_end_index','st_live_next_index','st_live_endpoint_role')
    for j,name in enumerate(names):attribute(mesh,name,'POINT',[p[j] for p in points]+[-1]*(len(mesh.vertices)-len(points)))
    for j,name in enumerate(('st_live_edge_index','st_live_first_edge_index','st_live_section_id','st_live_v0','st_live_v1')):
        attribute(mesh,name,'EDGE',[e[j] for e in edges])
    names=('st_live_seam_index','st_live_seam_neighbor_index','st_live_own_neighbor_index','st_live_seam_edge_index','st_live_own_edge_index','st_live_seam_offset_sign')
    for j,name in enumerate(names):
        attribute(mesh,name,'POINT',[seams.get(p[0],(-1,)*6)[j] for p in points]+[-1]*(len(mesh.vertices)-len(points)))
    required = nv if any(p[0] in seams for p in points) else -1
    attribute(mesh,'st_live_required_nv','POINT',[required]*len(mesh.vertices))
    mesh.update()
